#[derive(Debug, Clone)]
pub enum UapiDescriptor {
    Io(IoSubmitReq),
    ModelRangeDispatch(ModelRangeDispatchReq),
    BlockWriteback {
        block: BlockHash,
        task: Option<TaskKey>,
    },
    ShmemPut(ShmemPutReq),
    ShmemGet(ShmemGetReq),
    DfsRead(DfsReadReq),
    DfsWrite(DfsWriteReq),
    DbPut(DbPutReq),
    DbGet(DbGetReq),
    ObjectPublish(LingquObjectPublishReq),
    ObjectResolve(LingquObjectResolveReq),
    ObjectAppend(LingquObjectAppendReq),
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ModelRangeDispatchReq {
    pub op_id: u64,
    pub segment: SegmentHandle,
    pub task: TaskKey,
    pub object_ref_table_offset: u32,
    pub object_ref_count: u32,
}

#[derive(Debug, Clone)]
pub enum UapiCommand {
    QueryTopology,
    CreateSegment {
        bytes: u64,
    },
    RegisterCq {
        owner: EntityId,
    },
    CreateCmdQueue {
        cq: CqHandle,
        owner: EntityId,
        depth: usize,
    },
    EnqueueCmd {
        cmdq: CmdQueueHandle,
        owner: EntityId,
        desc: UapiDescriptor,
    },
    RingDoorbell {
        cmdq: CmdQueueHandle,
        owner: EntityId,
        max_batch: Option<usize>,
    },
    SubmitIo {
        req: IoSubmitReq,
    },
    SubmitBlockWriteback {
        block: BlockHash,
        task: Option<TaskKey>,
    },
    SubmitShmemPut {
        req: ShmemPutReq,
    },
    SubmitShmemGet {
        req: ShmemGetReq,
    },
    SubmitDfsRead {
        req: DfsReadReq,
    },
    SubmitDfsWrite {
        req: DfsWriteReq,
    },
    SubmitDbPut {
        req: DbPutReq,
    },
    SubmitDbGet {
        req: DbGetReq,
    },
    SubmitObjectPublish {
        req: LingquObjectPublishReq,
    },
    SubmitObjectResolve {
        req: LingquObjectResolveReq,
    },
    SubmitObjectAppend {
        req: LingquObjectAppendReq,
    },
    PollCq {
        cq: CqHandle,
        owner: EntityId,
        max_entries: Option<usize>,
    },
    DrainCq {
        cq: CqHandle,
        owner: EntityId,
    },
    GetHealth {
        entity: EntityId,
    },
}

#[derive(Debug, Clone)]
pub enum UapiResponse {
    TopologySnapshot(TopologySnapshot),
    SegmentCreated(SegmentHandle),
    CqRegistered(CqHandle),
    CmdQueueCreated(CmdQueueHandle),
    IoSubmitted(u64),
    CommandEnqueued {
        depth: usize,
        remaining_capacity: usize,
    },
    DoorbellRung {
        submitted: usize,
        pending: usize,
    },
    Completions {
        events: Vec<CompletionEvent>,
        remaining: usize,
    },
    HealthStatus(HealthStatus),
}

pub trait GuestUapiSurface {
    fn query_topology(&self) -> TopologySnapshot;
    fn create_segment(&mut self, bytes: u64) -> Result<SegmentHandle, SimError>;
    fn register_cq(&mut self) -> Result<CqHandle, SimError>;
    fn submit_io(&mut self, req: IoSubmitReq) -> Result<u64, SimError>;
    fn poll_cq(&self, cq: CqHandle) -> Vec<CompletionEvent>;
    fn get_health(&self, entity: EntityId) -> Result<HealthStatus, SimError>;
}

pub struct LocalGuestUapiSurface {
    topology: SimTopology,
    block_service: BlockServiceStub,
    shmem_service: ShmemServiceStub,
    dfs_service: DfsServiceStub,
    db_service: DbServiceStub,
    object_service: LingquObjectServiceStub,
    segment_payloads: HashMap<SegmentHandle, Vec<u8>>,
    model_runtime_object_payloads:
        HashMap<ModelRuntimeObjectCacheKey, Arc<ModelRuntimeObjectPayload>>,
    block_payloads: HashMap<BlockHash, Vec<u8>>,
    next_segment_id: u64,
    next_cq_id: u32,
    next_cmdq_id: u32,
    service_clock: u64,
    runtime_issue_latency_us: u64,
    runtime_retry_delay_us: u64,
    runtime_queue_depth: usize,
    runtime_max_retries: u32,
    cq_events: HashMap<CqHandle, CompletionQueueState>,
    cmd_queues: HashMap<CmdQueueHandle, CommandQueueState>,
    runtime_queue: SharedRuntimeExecutor<RuntimeWorkItem<UapiRuntimePayload>>,
    completion_routes: RuntimeCompletionTracker<CqHandle>,
}

impl std::fmt::Debug for LocalGuestUapiSurface {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("LocalGuestUapiSurface")
            .field("topology", &self.topology)
            .field("block_service", &self.block_service)
            .field("shmem_service", &self.shmem_service)
            .field("dfs_service", &self.dfs_service)
            .field("db_service", &self.db_service)
            .field("object_service", &self.object_service)
            .field("segment_payloads", &self.segment_payloads)
            .field(
                "model_runtime_object_payloads",
                &self.model_runtime_object_payloads.len(),
            )
            .field("block_payloads", &self.block_payloads)
            .field("next_segment_id", &self.next_segment_id)
            .field("next_cq_id", &self.next_cq_id)
            .field("next_cmdq_id", &self.next_cmdq_id)
            .field("service_clock", &self.service_clock)
            .field("runtime_issue_latency_us", &self.runtime_issue_latency_us)
            .field("runtime_retry_delay_us", &self.runtime_retry_delay_us)
            .field("runtime_queue_depth", &self.runtime_queue_depth)
            .field("runtime_max_retries", &self.runtime_max_retries)
            .field("cq_events", &self.cq_events)
            .field("cmd_queues", &self.cmd_queues)
            .field("runtime_queue", &self.runtime_queue)
            .field("completion_routes", &self.completion_routes)
            .finish()
    }
}

