fn simpler_manifest_has_current_capi_abi(manifest_path: &Path) -> bool {
    let Some(manifest) = std::fs::read_to_string(manifest_path)
        .ok()
        .and_then(|text| serde_json::from_str::<serde_json::Value>(&text).ok())
    else {
        return false;
    };
    manifest["simpler_capi_abi_version"].as_u64() == Some(3)
        && simpler_manifest_uses_portable_sim_kernel(&manifest)
        && simpler_manifest_runtime_matches_current_build(&manifest)
}

fn simpler_manifest_uses_portable_sim_kernel(manifest: &serde_json::Value) -> bool {
    manifest["sim_kernel_libgcc"].as_str() == Some("static")
}

fn simpler_manifest_runtime_matches_current_build(manifest: &serde_json::Value) -> bool {
    let repo_root = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .and_then(Path::parent)
        .map(Path::to_path_buf)
        .unwrap_or_else(|| PathBuf::from("."));
    let build_lib = repo_root.join("vendor/simpler/build/lib");
    if !build_lib.is_dir() {
        return true;
    }
    simpler_manifest_runtime_matches_build_lib(manifest, &build_lib)
}

fn simpler_manifest_runtime_matches_build_lib(
    manifest: &serde_json::Value,
    build_lib: &Path,
) -> bool {
    let runtime_dir = build_lib.join("a2a3/sim/host_build_graph");
    let artifacts = [
        (
            &manifest["simpler_runtime"]["host_runtime_library"]["source"],
            runtime_dir.join("libhost_runtime.so"),
        ),
        (
            &manifest["simpler_runtime"]["aicpu_binary"]["source"],
            runtime_dir.join("libaicpu_kernel.so"),
        ),
        (
            &manifest["simpler_runtime"]["aicore_binary"]["source"],
            runtime_dir.join("libaicore_kernel.so"),
        ),
        (
            &manifest["simpler_runtime"]["runtime_env"]["SIMPLER_LOG_LIBRARY"],
            build_lib.join("libsimpler_log.so"),
        ),
        (
            &manifest["simpler_runtime"]["runtime_env"]["SIMPLER_SIM_CONTEXT_LIBRARY"],
            build_lib.join("libcpu_sim_context.so"),
        ),
    ];
    artifacts.iter().all(|(cached_source, current)| {
        cached_source
            .as_str()
            .and_then(|cached| std::fs::read(cached).ok())
            .zip(std::fs::read(current).ok())
            .is_some_and(|(cached, current)| cached == current)
    })
}

fn simpler_engram_context_manifest_path() -> Result<PathBuf, String> {
    let path = std::env::var("SIMPLER_HOST_ENGRAM_CONTEXT_MANIFEST").unwrap_or_else(|_| {
        "/tmp/simpler-host-engram-context-artifacts/host_engram_context_manifest.json".to_string()
    });
    let path = PathBuf::from(path);
    if !simpler_host_engram_context_manifest_current(&path) {
        ensure_simpler_host_engram_context_manifest(&path)?;
    }
    if !path.exists() {
        return Err(format!(
            "missing_simpler_host_engram_context_manifest:{}",
            path.display()
        ));
    }
    Ok(path)
}

fn simpler_host_engram_context_manifest_current(manifest_path: &Path) -> bool {
    if !manifest_path.exists() {
        return false;
    }
    let Ok(text) = std::fs::read_to_string(manifest_path) else {
        return false;
    };
    let Ok(value) = serde_json::from_str::<serde_json::Value>(&text) else {
        return false;
    };
    simpler_manifest_has_current_capi_abi(manifest_path)
        && value
            .get("host_engram_context_manifest_version")
            .and_then(|version| version.as_u64())
            == Some(6)
        && value
            .get("simpler_runtime")
            .and_then(|runtime| runtime.get("runtime_env"))
            .and_then(|env| env.get("SIMPLER_LOG_LIBRARY"))
            .and_then(|path| path.as_str())
            .is_some_and(|path| !path.is_empty())
        && value
            .get("simpler_runtime")
            .and_then(|runtime| runtime.get("runtime_env"))
            .and_then(|env| env.get("SIMPLER_SIM_CONTEXT_LIBRARY"))
            .and_then(|path| path.as_str())
            .is_some_and(|path| !path.is_empty())
}

fn ensure_simpler_host_engram_context_manifest(manifest_path: &Path) -> Result<(), String> {
    let output_dir = manifest_path.parent().ok_or_else(|| {
        format!(
            "host_engram_context_manifest_has_no_parent:{}",
            manifest_path.display()
        )
    })?;
    let script = simpler_host_artifact_producer_path();
    if !script.exists() {
        return Err(format!(
            "missing_simpler_host_engram_context_artifact_producer:{}",
            script.display()
        ));
    }

    let mut command = std::process::Command::new("python3");
    command
        .arg(&script)
        .arg("--profile")
        .arg("host_engram_context")
        .arg("--output-dir")
        .arg(output_dir)
        .args(simpler_engram_context_reuse_runtime_args()?);
    let status = command
        .status()
        .map_err(|err| format!("run_simpler_host_engram_context_artifact_producer_failed:{err}"))?;
    if !status.success() {
        return Err(format!(
            "simpler_host_engram_context_artifact_producer_failed:{}:status={status}",
            script.display()
        ));
    }
    Ok(())
}

fn simpler_engram_context_reuse_runtime_args() -> Result<Vec<std::ffi::OsString>, String> {
    let matmul_manifest = std::env::var("SIMPLER_HOST_MATMUL_MANIFEST")
        .map(PathBuf::from)
        .unwrap_or_else(|_| {
            PathBuf::from("/tmp/simpler-host-matmul-artifacts/host_matmul_manifest.json")
        });
    ensure_simpler_host_matmul_manifest(&matmul_manifest)?;
    Ok(vec![
        std::ffi::OsString::from("--reuse-runtime-manifest"),
        matmul_manifest.into_os_string(),
    ])
}

