    // The native simpler runtime owns process-global state, so run each workload in a fresh test process.
    fn run_simpler_native_test_isolated(test_name: &str, body: impl FnOnce()) {
        const CHILD_ENV: &str = "SIM_UAPI_SIMPLER_NATIVE_TEST_CHILD";

        if std::env::var(CHILD_ENV).as_deref() == Ok(test_name) {
            body();
            return;
        }

        let current_exe = std::env::current_exe().expect("current test binary");
        let status = std::process::Command::new(current_exe)
            .arg(test_name)
            .arg("--nocapture")
            .arg("--test-threads=1")
            .env(CHILD_ENV, test_name)
            .status()
            .expect("run isolated simpler native test");
        assert!(
            status.success(),
            "isolated simpler native test {test_name} failed with {status}"
        );
    }

    fn with_env_var(name: &str, value: &str, body: impl FnOnce()) {
        let previous = std::env::var_os(name);
        std::env::set_var(name, value);
        body();
        match previous {
            Some(previous) => std::env::set_var(name, previous),
            None => std::env::remove_var(name),
        }
    }

    #[test]
    fn simpler_manifest_cache_requires_portable_sim_kernel_linkage() {
        let portable = serde_json::json!({"sim_kernel_libgcc": "static"});
        let host_bound = serde_json::json!({"sim_kernel_libgcc": "shared"});
        let legacy = serde_json::json!({});

        assert!(super::simpler_manifest_uses_portable_sim_kernel(&portable));
        assert!(!super::simpler_manifest_uses_portable_sim_kernel(
            &host_bound
        ));
        assert!(!super::simpler_manifest_uses_portable_sim_kernel(&legacy));
    }

    #[cfg(unix)]
    fn test_engram_simt_vendor_stub(case_name: &str) -> (PathBuf, PathBuf, PathBuf) {
        let root = std::env::temp_dir().join(format!(
            "ub_sim_qwen3_engram_simt_vendor_stub_{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&root);
        let build_dir = root.join("build");
        std::fs::create_dir_all(&build_dir).expect("create engram simt build dir");
        let binary_path = build_dir.join("engram-simt");
        let script = format!(
            "#!/bin/sh\ncase_dir='../data/{case_name}'\ntest -f \"$case_dir/table.bin\" || exit 7\ntest -f \"$case_dir/indices.bin\" || exit 8\ntest -f \"$case_dir/hidden.bin\" || exit 9\ntest -f \"$case_dir/gate_weight.bin\" || exit 10\ntest -f \"$case_dir/golden.bin\" || exit 11\nprintf '[PASS] {case_name}\\n'\nprintf '[engram-simt] Results: 1 passed, 0 failed, 1 total\\n'\n"
        );
        std::fs::write(&binary_path, script).expect("write engram simt stub binary");
        std::fs::set_permissions(&binary_path, Permissions::from_mode(0o755))
            .expect("chmod engram simt stub binary");
        let kernel_path = build_dir.join("libengram-simt_kernel.so");
        std::fs::write(&kernel_path, b"stub").expect("write engram simt kernel stub");
        (root, binary_path, kernel_path)
    }

    fn test_f32_vec_to_le_bytes(values: &[f32]) -> Vec<u8> {
        let mut bytes = Vec::with_capacity(std::mem::size_of_val(values));
        for value in values {
            bytes.extend_from_slice(&value.to_le_bytes());
        }
        bytes
    }

    fn test_i32_vec_to_le_bytes(values: &[i32]) -> Vec<u8> {
        let mut bytes = Vec::with_capacity(std::mem::size_of_val(values));
        for value in values {
            bytes.extend_from_slice(&value.to_le_bytes());
        }
        bytes
    }

    fn test_publish_engram_context_state_ref(
        key_prefix: &str,
        hidden_size: usize,
        table_rows: usize,
    ) -> (Vec<f32>, Vec<i32>, Vec<f32>, LingquObmmObjectRefWire) {
        let table = (0..table_rows * hidden_size)
            .map(|index| ((index % 37) as f32 - 18.0) / 4096.0)
            .collect::<Vec<_>>();
        let indices = (0..ENGRAM_CONTEXT_INDICES_PER_BATCH)
            .map(|index| (index % table_rows) as i32)
            .collect::<Vec<_>>();
        let gate_weight = (0..hidden_size)
            .map(|index| ((index % 17) as f32 - 8.0) / 8192.0)
            .collect::<Vec<_>>();
        let table_payload = test_f32_vec_to_le_bytes(&table);
        let indices_payload = test_i32_vec_to_le_bytes(&indices);
        let gate_payload = test_f32_vec_to_le_bytes(&gate_weight);
        let table_ref = LingquObmmObjectRefWire::committed(
            QWEN3_DENSE_PROFILE_OBMM_KIND_ENGRAM_CONTEXT_TABLE,
            0,
            0,
            1,
            qwen3_lingqu_key_hash(&format!("{key_prefix}/table")),
            0,
            table_payload.len() as u64,
            qwen3_dense_reference_range_object_payload_checksum(&table_payload),
        );
        let indices_ref = LingquObmmObjectRefWire::committed(
            QWEN3_DENSE_PROFILE_OBMM_KIND_ENGRAM_CONTEXT_INDICES,
            0,
            0,
            1,
            qwen3_lingqu_key_hash(&format!("{key_prefix}/indices")),
            0,
            indices_payload.len() as u64,
            qwen3_dense_reference_range_object_payload_checksum(&indices_payload),
        );
        let gate_ref = LingquObmmObjectRefWire::committed(
            QWEN3_DENSE_PROFILE_OBMM_KIND_ENGRAM_CONTEXT_GATE_WEIGHT,
            0,
            0,
            1,
            qwen3_lingqu_key_hash(&format!("{key_prefix}/gate_weight")),
            0,
            gate_payload.len() as u64,
            qwen3_dense_reference_range_object_payload_checksum(&gate_payload),
        );
        qwen3_object_registry_put(&table_ref, &table_payload).expect("put table object");
        qwen3_object_registry_put(&indices_ref, &indices_payload).expect("put indices object");
        qwen3_object_registry_put(&gate_ref, &gate_payload).expect("put gate object");
        let state_payload =
            qwen3_engram_state_manifest_payload(&table_ref, &indices_ref, &gate_ref)
                .expect("engram state manifest payload");
        let state_ref = LingquObmmObjectRefWire::committed(
            QWEN3_DENSE_PROFILE_OBMM_KIND_ENGRAM_STATE,
            0,
            0,
            1,
            qwen3_lingqu_key_hash(&format!("{key_prefix}/state")),
            0,
            state_payload.len() as u64,
            qwen3_dense_reference_range_object_payload_checksum(&state_payload),
        );
        qwen3_object_registry_put(&state_ref, &state_payload).expect("put state manifest object");
        (table, indices, gate_weight, state_ref)
    }

