    #[test]
    fn qwen3_engram_context_cpu_reference_consumes_object_ref_state() {
        run_simpler_native_test_isolated(
            "qwen3_engram_context_cpu_reference_consumes_object_ref_state",
            || {
                let registry_dir = std::env::temp_dir().join(format!(
                    "ub_sim_qwen3_engram_context_object_ref_test_{}",
                    std::process::id()
                ));
                let _ = std::fs::remove_dir_all(&registry_dir);
                let hidden_size = 1024usize;
                let table_rows = ENGRAM_CONTEXT_INDICES_PER_BATCH;
                let table = (0..table_rows * hidden_size)
                    .map(|index| ((index % 37) as f32 - 18.0) / 4096.0)
                    .collect::<Vec<_>>();
                let indices = (0..ENGRAM_CONTEXT_INDICES_PER_BATCH)
                    .map(|index| index as i32)
                    .collect::<Vec<_>>();
                let gate_weight = (0..hidden_size)
                    .map(|index| ((index % 17) as f32 - 8.0) / 8192.0)
                    .collect::<Vec<_>>();
                let table_payload = test_f32_vec_to_le_bytes(&table);
                let indices_payload = test_i32_vec_to_le_bytes(&indices);
                let gate_payload = test_f32_vec_to_le_bytes(&gate_weight);
                let table_ref = LingquObmmObjectRefWire::committed(
                    QWEN3_DENSE_PROFILE_OBMM_KIND_ENGRAM_CONTEXT_TABLE,
                    0,
                    0,
                    1,
                    qwen3_lingqu_key_hash("engram/context/table"),
                    0,
                    table_payload.len() as u64,
                    qwen3_dense_reference_range_object_payload_checksum(&table_payload),
                );
                let indices_ref = LingquObmmObjectRefWire::committed(
                    QWEN3_DENSE_PROFILE_OBMM_KIND_ENGRAM_CONTEXT_INDICES,
                    0,
                    0,
                    1,
                    qwen3_lingqu_key_hash("engram/context/indices"),
                    0,
                    indices_payload.len() as u64,
                    qwen3_dense_reference_range_object_payload_checksum(&indices_payload),
                );
                let gate_ref = LingquObmmObjectRefWire::committed(
                    QWEN3_DENSE_PROFILE_OBMM_KIND_ENGRAM_CONTEXT_GATE_WEIGHT,
                    0,
                    0,
                    1,
                    qwen3_lingqu_key_hash("engram/context/gate_weight"),
                    0,
                    gate_payload.len() as u64,
                    qwen3_dense_reference_range_object_payload_checksum(&gate_payload),
                );
                with_env_var(
                    SIM_UAPI_QWEN3_OBJECT_REGISTRY_DIR,
                    registry_dir.to_string_lossy().as_ref(),
                    || {
                        qwen3_object_registry_put(&table_ref, &table_payload)
                            .expect("put table object");
                        qwen3_object_registry_put(&indices_ref, &indices_payload)
                            .expect("put indices object");
                        qwen3_object_registry_put(&gate_ref, &gate_payload)
                            .expect("put gate object");
                        let state_payload = qwen3_engram_state_manifest_payload(
                            &table_ref,
                            &indices_ref,
                            &gate_ref,
                        )
                        .expect("engram state manifest payload");
                        let state_ref = LingquObmmObjectRefWire::committed(
                            QWEN3_DENSE_PROFILE_OBMM_KIND_ENGRAM_STATE,
                            0,
                            0,
                            1,
                            qwen3_lingqu_key_hash("engram/context/state"),
                            0,
                            state_payload.len() as u64,
                            qwen3_dense_reference_range_object_payload_checksum(&state_payload),
                        );
                        qwen3_object_registry_put(&state_ref, &state_payload)
                            .expect("put state manifest object");
                        with_env_var("SIM_QWEN3_GUEST_ENGRAM_CONTEXT_OP", "cpu-reference", || {
                            with_env_var(
                                SIM_QWEN3_GUEST_ENGRAM_STATE_REF,
                                &qwen3_obmm_object_ref_wire_to_hex(&state_ref),
                                || {
                                    let terminal_hidden = (0..hidden_size)
                                        .map(|index| {
                                            (index as f32 - hidden_size as f32 / 2.0) / 4096.0
                                        })
                                        .collect::<Vec<_>>();
                                    let expected = run_engram_context_reference(&EngramContextOp {
                                        table: &table,
                                        table_rows,
                                        indices: &indices,
                                        hidden: &terminal_hidden,
                                        gate_weight: &gate_weight,
                                        batch: 1,
                                        hidden_size,
                                    })
                                    .expect("reference state-ref context");
                                    let mut sequence =
                                        vec![vec![0.0f32; hidden_size], terminal_hidden];
                                    let report =
                                        qwen3_dense_reference_apply_engram_context_to_terminal_sequence(
                                            &mut sequence,
                                            &[11, 358, 2776, 264],
                                            QWEN3_DENSE_REFERENCE_PROFILE.num_hidden_layers,
                                            QWEN3_DENSE_REFERENCE_PROFILE.num_hidden_layers,
                                            None,
                                        )
                                        .expect("state-ref context op should run")
                                        .expect("context report");

                                    assert_eq!(report.mode, "cpu-reference-object-ref");
                                    assert_eq!(report.table_rows, table_rows);
                                    assert_eq!(
                                        report.output_checksum,
                                        expected.report.output_checksum
                                    );
                                    assert_eq!(sequence[1], expected.output);

                                    let mut nonterminal_sequence =
                                        vec![vec![0.0f32; hidden_size], expected.output.clone()];
                                    let nonterminal_before = nonterminal_sequence.clone();
                                    let skipped =
                                        qwen3_dense_reference_apply_engram_context_to_terminal_sequence(
                                            &mut nonterminal_sequence,
                                            &[11, 358, 2776, 264],
                                            QWEN3_DENSE_REFERENCE_PROFILE.num_hidden_layers - 1,
                                            QWEN3_DENSE_REFERENCE_PROFILE.num_hidden_layers,
                                            None,
                                        )
                                        .expect("legacy context op should skip non-terminal layer");
                                    assert!(skipped.is_none());
                                    assert_eq!(nonterminal_sequence, nonterminal_before);
                                },
                            );
                        });
                        with_env_var("SIM_QWEN3_GUEST_ENGRAM_CONTEXT_OP", "cpu-reference", || {
                            with_env_var(
                                SIM_QWEN3_GUEST_ENGRAM_CONTEXT_TABLE_REF,
                                &qwen3_obmm_object_ref_wire_to_hex(&table_ref),
                                || {
                                    with_env_var(
                                        SIM_QWEN3_GUEST_ENGRAM_CONTEXT_INDICES_REF,
                                        &qwen3_obmm_object_ref_wire_to_hex(&indices_ref),
                                        || {
                                            with_env_var(
                                                SIM_QWEN3_GUEST_ENGRAM_CONTEXT_GATE_WEIGHT_REF,
                                                &qwen3_obmm_object_ref_wire_to_hex(&gate_ref),
                                                || {
                                                    let terminal_hidden = (0..hidden_size)
                                                        .map(|index| {
                                                            (index as f32
                                                                - hidden_size as f32 / 2.0)
                                                                / 4096.0
                                                        })
                                                        .collect::<Vec<_>>();
                                                    let expected = run_engram_context_reference(
                                                        &EngramContextOp {
                                                            table: &table,
                                                            table_rows,
                                                            indices: &indices,
                                                            hidden: &terminal_hidden,
                                                            gate_weight: &gate_weight,
                                                            batch: 1,
                                                            hidden_size,
                                                        },
                                                    )
                                                    .expect("reference object-ref context");
                                                    let mut sequence = vec![
                                                        vec![0.0f32; hidden_size],
                                                        terminal_hidden,
                                                    ];
                                                    let report =
                                                        qwen3_dense_reference_apply_engram_context_to_terminal_sequence(
                                                            &mut sequence,
                                                            &[11, 358, 2776, 264],
                                                            QWEN3_DENSE_REFERENCE_PROFILE.num_hidden_layers,
                                                            QWEN3_DENSE_REFERENCE_PROFILE.num_hidden_layers,
                                                            None,
                                                        )
                                                        .expect("context op should run")
                                                        .expect("context report");

                                                    assert_eq!(
                                                        report.mode,
                                                        "cpu-reference-object-ref"
                                                    );
                                                    assert_eq!(report.table_rows, table_rows);
                                                    assert_eq!(
                                                        report.output_checksum,
                                                        expected.report.output_checksum
                                                    );
                                                    assert_eq!(sequence[1], expected.output);

                                                    let mut missing_descriptor_sequence = vec![
                                                        vec![0.0f32; hidden_size],
                                                        (0..hidden_size)
                                                            .map(|index| {
                                                                (index as f32
                                                                    - hidden_size as f32 / 2.0)
                                                                    / 4096.0
                                                            })
                                                            .collect::<Vec<_>>(),
                                                    ];
                                                    let missing_descriptor_payload = vec![
                                                        0u8;
                                                        QWEN3_DENSE_PROFILE_OBJECT_REF_TABLE_OFFSET
                                                            + QWEN3_DENSE_PROFILE_OBJECT_REF_MAX_COUNT
                                                                * LingquObmmObjectRefWire::BYTE_LEN
                                                    ];
                                                    let err =
                                                        qwen3_dense_reference_apply_engram_context_to_terminal_sequence(
                                                            &mut missing_descriptor_sequence,
                                                            &[11, 358, 2776, 264],
                                                            QWEN3_DENSE_REFERENCE_PROFILE.num_hidden_layers,
                                                            QWEN3_DENSE_REFERENCE_PROFILE.num_hidden_layers,
                                                            Some(&missing_descriptor_payload),
                                                        )
                                                        .expect_err("guest-input path must not fall back to env refs");
                                                    assert!(
                                                        err.contains("descriptor_refs_missing"),
                                                        "{err}"
                                                    );
                                                },
                                            );
                                        },
                                    );
                                },
                            );
                        });
                        with_env_var("SIM_QWEN3_GUEST_ENGRAM_CONTEXT_OP", "cpu-reference", || {
                            let terminal_hidden = (0..hidden_size)
                                .map(|index| (index as f32 - hidden_size as f32 / 2.0) / 4096.0)
                                .collect::<Vec<_>>();
                            let expected = run_engram_context_reference(&EngramContextOp {
                                table: &table,
                                table_rows,
                                indices: &indices,
                                hidden: &terminal_hidden,
                                gate_weight: &gate_weight,
                                batch: 1,
                                hidden_size,
                            })
                            .expect("reference descriptor object-ref context");
                            let mut segment_payload = vec![
                                0u8;
                                QWEN3_DENSE_PROFILE_OBJECT_REF_TABLE_OFFSET
                                    + QWEN3_DENSE_PROFILE_OBJECT_REF_MAX_COUNT
                                        * LingquObmmObjectRefWire::BYTE_LEN
                            ];
                            write_obmm_object_ref_wire(
                                &mut segment_payload[QWEN3_DENSE_PROFILE_OBJECT_REF_TABLE_OFFSET
                                    ..QWEN3_DENSE_PROFILE_OBJECT_REF_TABLE_OFFSET
                                        + LingquObmmObjectRefWire::BYTE_LEN],
                                table_ref,
                            );
                            write_obmm_object_ref_wire(
                                &mut segment_payload[QWEN3_DENSE_PROFILE_OBJECT_REF_TABLE_OFFSET
                                    + LingquObmmObjectRefWire::BYTE_LEN
                                    ..QWEN3_DENSE_PROFILE_OBJECT_REF_TABLE_OFFSET
                                        + LingquObmmObjectRefWire::BYTE_LEN * 2],
                                indices_ref,
                            );
                            write_obmm_object_ref_wire(
                                &mut segment_payload[QWEN3_DENSE_PROFILE_OBJECT_REF_TABLE_OFFSET
                                    + LingquObmmObjectRefWire::BYTE_LEN * 2
                                    ..QWEN3_DENSE_PROFILE_OBJECT_REF_TABLE_OFFSET
                                        + LingquObmmObjectRefWire::BYTE_LEN * 3],
                                gate_ref,
                            );
                            let mut sequence = vec![vec![0.0f32; hidden_size], terminal_hidden];
                            let report =
                                qwen3_dense_reference_apply_engram_context_to_terminal_sequence(
                                    &mut sequence,
                                    &[11, 358, 2776, 264],
                                    QWEN3_DENSE_REFERENCE_PROFILE.num_hidden_layers,
                                    QWEN3_DENSE_REFERENCE_PROFILE.num_hidden_layers,
                                    Some(&segment_payload),
                                )
                                .expect("descriptor context op should run")
                                .expect("context report");

                            assert_eq!(report.mode, "cpu-reference-object-ref");
                            assert_eq!(report.table_rows, table_rows);
                            assert_eq!(report.output_checksum, expected.report.output_checksum);
                            assert_eq!(sequence[1], expected.output);
                        });
                        with_env_var("SIM_QWEN3_GUEST_ENGRAM_CONTEXT_OP", "cpu-reference", || {
                            let terminal_hidden = (0..hidden_size)
                                .map(|index| (index as f32 - hidden_size as f32 / 2.0) / 4096.0)
                                .collect::<Vec<_>>();
                            let expected = run_engram_context_reference(&EngramContextOp {
                                table: &table,
                                table_rows,
                                indices: &indices,
                                hidden: &terminal_hidden,
                                gate_weight: &gate_weight,
                                batch: 1,
                                hidden_size,
                            })
                            .expect("reference descriptor state-ref context");
                            let mut segment_payload = vec![
                                0u8;
                                QWEN3_DENSE_PROFILE_OBJECT_REF_TABLE_OFFSET
                                    + QWEN3_DENSE_PROFILE_OBJECT_REF_MAX_COUNT
                                        * LingquObmmObjectRefWire::BYTE_LEN
                            ];
                            write_obmm_object_ref_wire(
                                &mut segment_payload[QWEN3_DENSE_PROFILE_OBJECT_REF_TABLE_OFFSET
                                    ..QWEN3_DENSE_PROFILE_OBJECT_REF_TABLE_OFFSET
                                        + LingquObmmObjectRefWire::BYTE_LEN],
                                state_ref,
                            );
                            let mut sequence = vec![vec![0.0f32; hidden_size], terminal_hidden];
                            let report =
                                qwen3_dense_reference_apply_engram_context_to_terminal_sequence(
                                    &mut sequence,
                                    &[11, 358, 2776, 264],
                                    QWEN3_DENSE_REFERENCE_PROFILE.num_hidden_layers,
                                    QWEN3_DENSE_REFERENCE_PROFILE.num_hidden_layers,
                                    Some(&segment_payload),
                                )
                                .expect("descriptor state-ref context op should run")
                                .expect("context report");

                            assert_eq!(report.mode, "cpu-reference-object-ref");
                            assert_eq!(report.table_rows, table_rows);
                            assert_eq!(report.output_checksum, expected.report.output_checksum);
                            assert_eq!(sequence[1], expected.output);
                        });
                        with_env_var("SIM_QWEN3_GUEST_ENGRAM_CONTEXT_OP", "cpu-reference", || {
                            let mut sequence = vec![
                                vec![0.0f32; hidden_size],
                                (0..hidden_size)
                                    .map(|index| (index as f32 - hidden_size as f32 / 2.0) / 4096.0)
                                    .collect::<Vec<_>>(),
                            ];
                            let empty_descriptor_payload = vec![
                                0u8;
                                QWEN3_DENSE_PROFILE_OBJECT_REF_TABLE_OFFSET
                                    + QWEN3_DENSE_PROFILE_OBJECT_REF_MAX_COUNT
                                        * LingquObmmObjectRefWire::BYTE_LEN
                            ];
                            let err =
                                qwen3_dense_reference_apply_engram_context_to_terminal_sequence(
                                    &mut sequence,
                                    &[11, 358, 2776, 264],
                                    QWEN3_DENSE_REFERENCE_PROFILE.num_hidden_layers,
                                    QWEN3_DENSE_REFERENCE_PROFILE.num_hidden_layers,
                                    Some(&empty_descriptor_payload),
                                )
                                .expect_err(
                                    "guest-input context op must require descriptor object refs",
                                );
                            assert!(err.contains("descriptor_refs_required"), "{err}");
                        });
                    },
                );
                let _ = std::fs::remove_dir_all(&registry_dir);
            },
        );
    }

    #[test]
    fn qwen3_engram_context_simpler_host_supports_multi_chunk_hidden() {
        run_simpler_native_test_isolated(
            "qwen3_engram_context_simpler_host_supports_multi_chunk_hidden",
            || {
                let registry_dir = std::env::temp_dir().join(format!(
                    "ub_sim_qwen3_engram_context_simpler_chunk_test_{}",
                    std::process::id()
                ));
                let _ = std::fs::remove_dir_all(&registry_dir);
                with_env_var(
                    SIM_UAPI_QWEN3_OBJECT_REGISTRY_DIR,
                    registry_dir.to_string_lossy().as_ref(),
                    || {
                        let hidden_size = 256usize;
                        let table_rows = ENGRAM_CONTEXT_INDICES_PER_BATCH;
                        let (_table, _indices, _gate_weight, state_ref) =
                            test_publish_engram_context_state_ref(
                                "engram/context/simpler-chunk",
                                hidden_size,
                                table_rows,
                            );
                        with_env_var("SIM_QWEN3_GUEST_ENGRAM_CONTEXT_OP", "simpler-host", || {
                            with_env_var(
                                SIM_QWEN3_GUEST_ENGRAM_STATE_REF,
                                &qwen3_obmm_object_ref_wire_to_hex(&state_ref),
                                || {
                                    with_env_var(
                                        "SIM_QWEN3_GUEST_ENGRAM_CONTEXT_CHUNK_ELEMS",
                                        "128",
                                        || {
                                            let mut sequence = vec![
                                                vec![0.0f32; hidden_size],
                                                (0..hidden_size)
                                                    .map(|index| {
                                                        (index as f32 - hidden_size as f32 / 2.0)
                                                            / 2048.0
                                                    })
                                                    .collect::<Vec<_>>(),
                                            ];
                                            let terminal_before = sequence[1].clone();
                                            let report =
                                                qwen3_dense_reference_apply_engram_context_to_terminal_sequence(
                                                    &mut sequence,
                                                    &[11, 358, 2776, 264],
                                                    QWEN3_DENSE_REFERENCE_PROFILE.num_hidden_layers,
                                                    QWEN3_DENSE_REFERENCE_PROFILE.num_hidden_layers,
                                                    None,
                                                )
                                                .expect("multi-chunk simpler-host context op should run")
                                                .expect("context report");

                                            assert_eq!(report.mode, "simpler-host-object-ref");
                                            assert_eq!(report.table_rows, table_rows);
                                            assert_ne!(report.output_checksum, 0);
                                            assert_ne!(sequence[1], terminal_before);
                                        },
                                    );
                                },
                            );
                        });
                    },
                );
                let _ = std::fs::remove_dir_all(&registry_dir);
            },
        );
    }

