        let mut guest_input = vec![0u8; QWEN3_DENSE_PROFILE_RANGE_INPUT_PAYLOAD_OFFSET + 64];
        guest_input[QWEN3_DENSE_PROFILE_RANGE_INPUT_PAYLOAD_OFFSET
            ..QWEN3_DENSE_PROFILE_RANGE_INPUT_PAYLOAD_OFFSET + 64]
