            if checksum != 0 {
                result_block_checksum_nonzero += 1;
            }
            if checksum == expected_checksum {
                result_block_checksum_matches += 1;
            }
            if block == 0 {
                result_block_checksum_first = checksum;
            }
            result_block_checksum_last = checksum;
