    fn test_topology() -> SimTopology {
        let config = ScenarioConfig::from_yaml_str(VALID_YAML).expect("valid config");
        SimTopology::from_config(&config).expect("topology")
    }

    fn test_surface() -> LocalGuestUapiSurface {
        LocalGuestUapiSurface::new(test_topology())
    }

    #[test]
    fn dispatch_result_write_rejects_oversized_output() {
        let mut surface = test_surface();
        let segment = surface.create_segment(4).expect("create segment");
        let err = surface
            .write_dispatch_result_to_segment(segment, &[1, 2, 3, 4, 5])
            .expect_err("oversized dispatch output must fail");

        assert!(matches!(
            err,
            SimError::InvalidInput("dispatch result exceeds segment payload")
        ));
        assert_eq!(
            surface
                .segment_payloads
                .get(&segment)
                .expect("segment")
                .as_slice(),
            &[0, 0, 0, 0]
        );
    }

